import{_ as i,C as t,o as r,c as l,j as n,a as d,E as a,a6 as c}from"./chunks/framework.CD0vXS2f.js";const A=JSON.parse('{"title":"02 · Three-Tier ACA Sandboxed Runtime, AG-UI SSE & Document Pipeline","description":"Reference design for isolating enterprise agent execution using a stateless orchestrator, microVM ACA session pools, typed AG-UI SSE events, and Azure Content Understanding.","frontmatter":{"title":"02 · Three-Tier ACA Sandboxed Runtime, AG-UI SSE & Document Pipeline","description":"Reference design for isolating enterprise agent execution using a stateless orchestrator, microVM ACA session pools, typed AG-UI SSE events, and Azure Content Understanding."},"headers":[],"relativePath":"playbooks/agentic-rag-evals/02-sandboxed-agent-harness.md","filePath":"playbooks/agentic-rag-evals/02-sandboxed-agent-harness.md","lastUpdated":1795280666087}'),p={name:"playbooks/agentic-rag-evals/02-sandboxed-agent-harness.md"};function g(u,e,h,m,f,v){const s=t("PlaybookMeta"),o=t("PageBrief");return r(),l("div",null,[e[0]||(e[0]=n("h1",{id:"_02-·-three-tier-aca-sandboxed-runtime-ag-ui-sse-document-pipeline",tabindex:"-1"},[d("02 · Three-Tier ACA Sandboxed Runtime, AG-UI SSE & Document Pipeline "),n("a",{class:"header-anchor",href:"#_02-·-three-tier-aca-sandboxed-runtime-ag-ui-sse-document-pipeline","aria-label":'Permalink to "02 · Three-Tier ACA Sandboxed Runtime, AG-UI SSE & Document Pipeline"'},"​")],-1)),a(s,{track:"04 · Sandboxed Agentic Harness, Foundry IQ RAG & 7-Layer Evals",verified:"2026-11-19 PST",status:"Live v2.0",studioHref:"/studio/#agent-eval",studioLabel:"Size ACA Session Pool →"}),a(o,{stage:"design",readTime:"5 min read",problem:"Co-locating LLM agent SDKs, shell/Python tools, and user-uploaded documents inside a multi-tenant FastAPI/Node server creates path-traversal, credential-exfiltration, and noisy-neighbor risks.",takeaway:"Keep the orchestrator 100% SDK-free: forward scoped bearer tokens and proxy typed AG-UI SSE events line-by-line from microVM-isolated ACA Session Containers, deploying images strictly by Git SHA.",csaUse:"Use these five architectural invariants as the security review baseline for any code-executing or file-processing enterprise agent."}),e[1]||(e[1]=c(`<h2 id="_1-five-architectural-invariants-of-the-3-tier-agent-harness-arch" tabindex="-1">1. Five Architectural Invariants of the 3-Tier Agent Harness <code>[Arch]</code> <a class="header-anchor" href="#_1-five-architectural-invariants-of-the-3-tier-agent-harness-arch" aria-label="Permalink to &quot;1. Five Architectural Invariants of the 3-Tier Agent Harness \`[Arch]\`&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Invariant</th><th style="text-align:left;">Implementation Mechanism</th><th style="text-align:left;">Failure Prevented</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. Orchestrator Never Runs the Agent SDK</strong></td><td style="text-align:left;">The public-facing orchestrator validates session IDs (<code>^[0-9a-f]{16}$</code>), mints short-lived <code>DefaultAzureCredential</code> Cognitive Services tokens, and proxies SSE lines with <strong>zero buffering</strong>.</td><td style="text-align:left;">Eliminates arbitrary code/tool execution and filesystem cross-contamination on the shared control plane.</td></tr><tr><td style="text-align:left;"><strong>2. One MicroVM Container Per Session</strong></td><td style="text-align:left;">Production allocates isolated containers via <strong>Azure Container Apps Dynamic Sessions / Sandbox Pools</strong> (<code>cooldown=300s</code>, <code>ready-sessions</code> tuned to concurrency) <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Hypervisor-level memory, network, and <code>WORKSPACE</code> filesystem isolation per user session <span class="ev-badge ev-m">[M]</span>.</td></tr><tr><td style="text-align:left;"><strong>3. Strict Upload Sanitization + Content Understanding</strong></td><td style="text-align:left;">Enforce extension allowlists, <code>50 MB</code> streaming size caps, and <code>os.path.realpath(dest)</code> workspace containment; convert binary PDFs/DOCX/XLSX via <strong>ADLS Gen2 + Azure Content Understanding</strong> into clean <code>.md</code> siblings <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Prevents path traversal (<code>../</code>) while giving the LLM table-accurate Markdown instead of garbled PDF text extraction.</td></tr><tr><td style="text-align:left;"><strong>4. Typed <code>AG-UI</code> Streaming Protocol</strong></td><td style="text-align:left;">Emit structured <code>RUN_STARTED</code>, <code>TEXT_MESSAGE_START/CONTENT/END</code>, <code>TOOL_CALL_START/ARGS/END</code>, <code>RUN_ERROR</code>, and <code>RUN_FINISHED</code> JSON SSE frames (suppressing internal SDK plumbing tools).</td><td style="text-align:left;">Deterministic frontend <code>useReducer</code> state transitions with clean timeout/error terminal states.</td></tr><tr><td style="text-align:left;"><strong>5. Immutable Git-SHA Image Tags (Never <code>:latest</code>)</strong></td><td style="text-align:left;">Tag and deploy all ACA apps and session pools with <code>git rev-parse --short HEAD</code> (<code>repo:$SHA</code>).</td><td style="text-align:left;">Azure Container Apps caches tag-to-digest resolution per revision string—deploying <code>:latest</code> silently no-ops and leaves stale code running!</td></tr></tbody></table><hr><h2 id="_2-document-upload-layout-faithful-conversion-flow" tabindex="-1">2. Document Upload &amp; Layout-Faithful Conversion Flow <a class="header-anchor" href="#_2-document-upload-layout-faithful-conversion-flow" aria-label="Permalink to &quot;2. Document Upload &amp; Layout-Faithful Conversion Flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser (Multipart POST /sessions/{id}/upload, ≤50 MB)</span></span>
<span class="line"><span>  └─► Orchestrator</span></span>
<span class="line"><span>        1. Stream-validate size + sanitize filename (PurePosixPath(name).name)</span></span>
<span class="line"><span>        2. Forward raw file to Session Container WORKSPACE + record in .uploaded_files.json</span></span>
<span class="line"><span>        3. Persist original binary to ADLS Gen2 (documents/{session_id}/{filename})</span></span>
<span class="line"><span>        4. Convert to Markdown:</span></span>
<span class="line"><span>             • UTF-8 text/CSV/JSON/XML → direct verified decode</span></span>
<span class="line"><span>             • Binary PDF / DOCX / PPTX / XLSX → Azure Content Understanding layout extraction [M]</span></span>
<span class="line"><span>        5. Persist {filename}.md to ADLS + forward {filename}.md into Session Container WORKSPACE</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Fail-Closed Document Processing</p><p>Do not silently fall back to lossy plain-text scraping when regulated financial tables or compliance schedules fail conversion. Return an explicit <code>503</code> / actionable conversion status so agents never score incomplete tables <span class="ev-badge ev-arch">[Arch]</span>.</p></div>`,6))])}const y=i(p,[["render",g]]);export{A as __pageData,y as default};
